"""PT1 personal-topic grid and continuous Section reader, using synthetic data."""
from html import escape


def topic_section(t, ctl, records):
    topics = [
        ('product', t('产品的第一步', 'A product’s first step'), [('explore', t('探索方向', 'Exploring a direction')), ('decisions', t('判断与取舍', 'Decisions and trade-offs'))]),
        ('writing', t('写作习惯', 'Writing practice'), [('clarity', t('先说清楚', 'Making the point')), ('revision', t('修改与取舍', 'Editing and choosing'))]),
        ('learning', t('学习与理解', 'Learning and understanding'), [('questions', t('从问题开始', 'Start with a question')), ('understand', t('形成自己的解释', 'Find your own explanation'))]),
    ]
    blocks = ''.join(f'''<article class="pc-topic-block" data-topic-block="{key}"><h3><a href="#pc-topic-{key}" data-topic-open="{key}">{title}</a></h3>{''.join(f'<a class="pc-section-anchor" href="#pc-section-{section}" data-topic-open="{key}">{label}</a>' for section, label in sections)}</article>''' for key, title, sections in topics)
    trails = [
        ('a', '12 AUG', '09:42', records[0][2], t('第一版应该做什么 · 最初的问题', 'What belongs in v1 · First question')),
        ('b', '26 AUG', '11:18', records[1][2], t('第一版应该做什么 · 缩小范围', 'What belongs in v1 · Narrowing the scope')),
        ('c', '10 SEP', '18:03', records[2][2], t('第一版应该做什么 · 判断标准', 'What belongs in v1 · Decision criterion')),
        ('note', '24 SEP', '10:26', t('保留这个取舍：先找回，再决定是否创造更多。', 'Keep this trade-off: recover first, then decide whether to create more.'), t('用户研究 · 保留的决定', 'User research · Decision retained')),
    ]
    def entry(row):
        key, date, time, body, source = row
        return f'''<article class="pc-thought" data-thought="{key}"><div class="pc-thought-stamp"><time>{date} <span>{time}</span></time></div><p data-thought-text="{key}">{escape(body)}</p><details class="pc-topic-source"><summary>{t('查看来源', 'View source')}</summary><p>ChatGPT · {source}</p></details></article>'''
    def reader_head(key, title):
        return f'''<div class="pc-topic-reader-head">{ctl('← ' + t('所有主题', 'All topics'), 'data-topic-back', 'pc-quiet')}<h3 id="pc-topic-{key}" tabindex="-1">{title}</h3></div>'''
    reading = f'''<div class="pc-reading-demo"><div><label for="pc-reading-style">{t('AI 整理的阅读方式', 'AI reading style')}</label><span class="pc-local-tag">{t('规划能力 · 预设示例', 'PLANNED · PRESET EXAMPLE')}</span></div><select id="pc-reading-style" data-reading-style disabled><option value="original">{t('原话优先', 'Original-first')}</option><option value="balanced">{t('平衡整理（默认）', 'Balanced (default)')}</option><option value="concise">{t('更加概括', 'More concise')}</option></select><div data-reading-output role="status"><p>{t('保留上方原话。整理只改变阅读呈现，不覆盖你的文字或主题组织。', 'Keep the words above. Organization changes the reading view, never your words or topic structure.')}</p></div><p class="pc-reading-source">{t('依据：上方 4 条示例表达 · 2 个对话。整理不是你的新观点。', 'Based on the four sample expressions above, from two conversations. An organized view is not a new opinion attributed to you.')}</p></div>'''
    product_reader = f'''<div class="pc-topic-reader" data-topic-reader="product">{reader_head('product', topics[0][1])}<div class="pc-thoughts"><section><h4 id="pc-section-explore" tabindex="-1">{topics[0][2][0][1]}</h4>{entry(trails[0])}{entry(trails[1])}</section><section><h4 id="pc-section-decisions" tabindex="-1">{topics[0][2][1][1]}</h4>{entry(trails[2])}{entry(trails[3])}</section></div>{reading}</div>'''
    writing_reader = f'''<div class="pc-topic-reader" data-topic-reader="writing">{reader_head('writing', topics[1][1])}<div class="pc-thoughts"><section><h4 id="pc-section-clarity" tabindex="-1">{topics[1][2][0][1]}</h4><p class="pc-reader-prose">{t('先把想说明的事情说清楚，再决定是否需要修饰。', 'Make the point clear first. Decide afterward whether it needs embellishment.')}</p></section><section><h4 id="pc-section-revision" tabindex="-1">{topics[1][2][1][1]}</h4><p class="pc-reader-prose">{t('每次修改，保留真正影响判断的细节。', 'Keep the details that actually change the judgment when editing.')}</p></section></div></div>'''
    learning_reader = f'''<div class="pc-topic-reader" data-topic-reader="learning">{reader_head('learning', topics[2][1])}<div class="pc-thoughts"><section><h4 id="pc-section-questions" tabindex="-1">{topics[2][2][0][1]}</h4><p class="pc-reader-prose">{t('把还没有想明白的问题留下来，下次从这里继续。', 'Keep the questions that are still unresolved. Begin here next time.')}</p></section><section><h4 id="pc-section-understand" tabindex="-1">{topics[2][2][1][1]}</h4><p class="pc-reader-prose">{t('能用自己的话解释，才算理解了一步。', 'Being able to explain it in my own words is one step toward understanding.')}</p></section></div></div>'''
    return f'''<section class="pc-section pc-topics wrap" id="thought-library" aria-labelledby="pc-topics-title"><div class="pc-heading"><div><p class="eyebrow">02 / THOUGHT LIBRARY</p><h2 id="pc-topics-title">{t('散落的想法，<br>有了自己的脉络。', 'Scattered ideas.<br>A thread of your own.')}</h2></div><div class="pc-intro"><p>{t('用你自己的主题和章节，把不同对话里的表达放在一起。打开一个主题，就能沿着原话连续读下去。计划中的 AI 整理，会提供不同详略的阅读方式，保留来源和你的决定。', 'Bring expressions from different conversations into your own topics and sections. Open a topic and keep reading your words. Planned AI organization offers different levels of detail while preserving sources and your decisions.')}</p><span class="pc-instruction">{t('打开主题，或直接跳到一个章节。', 'Open a topic, or go straight to a section.')} <span aria-hidden="true">↘</span></span></div></div>
<div class="pc-topic-stage pc-reveal" data-topic-stage><header class="pc-topic-toolbar"><span class="pc-app-name">Thought Library</span><span class="pc-local-tag">{t('虚构主题 · 非实时 AI', 'FICTIONAL TOPICS · NOT LIVE AI')}</span></header>
<div class="pc-topic-overview" data-topic-overview><div class="pc-topic-root-head"><h3>{t('我的主题', 'My topics')}</h3><label class="pc-topic-search"><span class="visually-hidden">{t('搜索示例主题', 'Search the example topics')}</span><input type="search" data-topic-search placeholder="{t('搜索主题与内容…', 'Find a topic or expression…')}" disabled></label></div><div class="pc-topic-grid">{blocks}</div><p class="pc-topic-match" data-topic-match role="status"></p></div>
{product_reader}{writing_reader}{learning_reader}
<footer class="pc-topic-footer"><span data-topic-status role="status">{t('主题 → 章节 → 你的原话。', 'Topics → Sections → Your words.')}</span><span class="pc-local-tag">{t('一个思想库，持续积累。', 'ONE LIBRARY. ROOM TO GROW.')}</span></footer></div>
<div class="pc-section-foot"><span>{t('按你的方式组织', 'ORGANIZED ON YOUR TERMS')}</span><p>{t('人工命名、移动和排除始终优先。多个位置引用同一份内容。', 'Your names, moves and exclusions take priority. Multiple placements refer to the same content.')}</p></div></section>'''
